import subprocess
def fd(n):
    if n==0: return (0,1)
    a,b=fd(n>>1); c=a*(2*b-a); d=a*a+b*b
    return (c,d) if n%2==0 else (d,c+d)
ref=lambda n: fd(n)[0]
bad=[]
for n in list(range(0,300))+[500,1000,2000]:
    p=subprocess.run(["python3","main.py.c",str(n)],capture_output=True,text=True)
    if p.stdout.strip()!=str(ref(n)): bad.append(("py",n,p.stdout.strip(),p.stderr.strip()[:80]))
for n in range(0,93):
    c=subprocess.run(["./cmain",str(n)],capture_output=True,text=True)
    if c.stdout.strip()!=str(ref(n)): bad.append(("c",n,c.stdout.strip(),c.stderr.strip()[:80]))
print("MISMATCHES:",bad)
print("f(0) f(1) f(2) f(10) f(92) py:",[subprocess.run(["python3","main.py.c",str(n)],capture_output=True,text=True).stdout.strip() for n in (0,1,2,10,92)])
print("f(0) f(1) f(2) f(10) f(92) c :",[subprocess.run(["./cmain",str(n)],capture_output=True,text=True).stdout.strip() for n in (0,1,2,10,92)])
print("f(93) c (overflow expected):",subprocess.run(["./cmain","93"],capture_output=True,text=True).stdout.strip())
